export function resolveClientApiBase(value?: string | null): string {
  const envBase = normalizeApiBase(import.meta.env.VITE_CLIENT_API_BASE);
  if (envBase) {
    return envBase;
  }
  if (import.meta.env.DEV) {
    const direct = normalizeApiBase(value);
    if (direct) {
      return direct;
    }
  }
  return DEFAULT_CLIENT_API_BASE;
}

TRUSTED_PROXIES = frozenset(os.environ.get("CLIENT_TRUSTED_PROXIES", "127.0.0.1").split(","))

def _rate_limit_key_ip(self) -> str:
    peer = self.client_address[0] if self.client_address else "unknown"
    if peer not in TRUSTED_PROXIES:
        return peer
    forwarded = self.headers.get("X-Forwarded-For", "").split(",")[0].strip()
    return forwarded or peer

def _rate_limit_check(self, path: str) -> bool:
    return self.server.rate_limiter.allow(f"{self._rate_limit_key_ip()}:{path}")

def resolve_user_id(handler: BaseHTTPRequestHandler) -> str:
    """Return the profile id from the signed session cookie, minting one if absent."""
    cookie = SimpleCookie(handler.headers.get("Cookie", ""))
    raw = cookie["ptb_sid"].value if "ptb_sid" in cookie else ""
    verified = verify_signed_session(raw)  # HMAC over the id with a server-side key
    return verified or issue_session(handler)

